.hero p{max-width:640px;margin:16px auto 28px;font-size:1.125rem;color:#374151}
.actions{display:flex;gap:12px;justify-content:center;flex-wrap:wrap}
.btn{display:inline-block;padding:12px 24px;border-radius:8px;font:inherit;font-weight:600;text-decoration:none;cursor:pointer;border:2px solid #1d4ed8;background:#1d4ed8;color:#fff;text-align:center}
.btn.secondary{background:#fff;color:#1d4ed8}
.btn:focus-visible,a:focus-visible,summary:focus-visible,input:focus-visible+span{outline:3px solid #f59e0b;outline-offset:2px}
