h2{font-size:1.75rem;margin-bottom:8px;color:#111827}
.lead{color:#4b5563;margin-bottom:28px}
.features{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;list-style:none;padding:0}
.features li{border:1px solid #d1d5db;border-radius:12px;padding:20px}
.features h3{margin-bottom:6px;color:#1e3a8a}
.toggle{display:inline-flex;border:2px solid #1d4ed8;border-radius:999px;overflow:hidden;margin-bottom:24px;padding:0;position:relative}
.toggle label{cursor:pointer}
.toggle input{position:absolute;opacity:0}
.toggle span{display:block;padding:8px 20px;color:#1d4ed8;font-weight:600}
.toggle input:checked+span{background:#1d4ed8;color:#fff}
legend{position:absolute;left:-9999px}
.plans{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;align-items:stretch}
.plan{border:1px solid #d1d5db;border-radius:12px;padding:24px;display:flex;flex-direction:column;gap:12px}
.plan.rec{border:2px solid #1d4ed8;box-shadow:0 4px 16px rgba(29,78,216,.15)}
.badge{align-self:flex-start;background:#92400e;color:#fff;font-size:.8rem;font-weight:700;padding:2px 10px;border-radius:999px}
.price{font-size:2rem;font-weight:800}
.price small{font-size:.9rem;font-weight:400;color:#4b5563}
.plan ul{padding-left:20px;flex:1}
.note{color:#4b5563;font-size:.9rem}
h3.sub{margin:36px 0 12px;font-size:1.25rem}
table{width:100%;border-collapse:collapse;table-layout:fixed}
caption{text-align:left;position:absolute;left:-9999px}
th,td{border:1px solid #d1d5db;padding:10px 8px;text-align:center;overflow-wrap:anywhere}
thead th{background:#eff6ff}
tbody th{text-align:left;background:#f9fafb}
.state{border:1px dashed #6b7280;border-radius:12px;padding:32px 20px;text-align:center}
.state.err{border:2px solid #b91c1c;background:#fef2f2}
.state.err h3{color:#b91c1c}
.state.emp{background:#f3f4f6}
.state h3{margin-bottom:8px;font-size:1.25rem}
.state .btn{margin-top:16px}
.spin{width:32px;height:32px;margin:0 auto 12px;border:4px solid #bfdbfe;border-top-color:#1d4ed8;border-radius:50%;animation:s 1s linear infinite}
@keyframes s{to{transform:rotate(360deg)}}
@media (prefers-reduced-motion:reduce){.spin{animation:none}}
details{border:1px solid #d1d5db;border-radius:8px;padding:12px 16px;margin-bottom:10px}
summary{cursor:pointer;font-weight:600}
details p{margin-top:8px;color:#374151}
footer{background:#111827;color:#e5e7eb;padding:32px 0;margin-top:24px}
footer a{color:#bfdbfe}
@media (max-width:900px){.features,.plans{grid-template-columns:1fr}}
@media (max-width:520px){th,td{font-size:.8rem;padding:8px 4px}section.block{padding:40px 14px}.nav{padding:16px 14px}}

